import { StyleSheet, View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

import { MARK_FRAME, MARK_INITIAL, MARK_VIEWBOX, WORDMARK_EVENTS, WORDMARK_LI, WORDMARK_SPARK, WORDMARK_VIEWBOX } from './brandPaths';
import { colors } from './theme';

/**
 * The logo from the brand kit (docs/brand): the yellow E-ticket and the
 * lowercase Urbanist Black word with the yellow spark. The paths are the kit's
 * own (brandPaths.ts, generated by frontend/scripts/brandLogo.js) — never
 * redrawn — so the app's logo IS the logo.
 */

const box = (vb: string) => {
  const [, , w, h] = vb.split(' ').map(Number);
  return { w, h };
};

export function Mark({ size = 40 }: { size?: number }) {
  const { w, h } = box(MARK_VIEWBOX);
  return (
    <Svg width={(size * w) / h} height={size} viewBox={MARK_VIEWBOX} accessible={false}>
      <Path d={MARK_FRAME} fill={colors.highlight} />
      <Path d={MARK_INITIAL} fill={colors.night} />
    </Svg>
  );
}

export function Wordmark({ height = 28, color = colors.night }: { height?: number; color?: string }) {
  const { w, h } = box(WORDMARK_VIEWBOX);
  return (
    <Svg width={(height * w) / h} height={height} viewBox={WORDMARK_VIEWBOX} accessible={false}>
      <Path d={WORDMARK_EVENTS} fill={color} />
      <Path d={WORDMARK_LI} fill={color} />
      <Path d={WORDMARK_SPARK} fill={colors.highlight} />
    </Svg>
  );
}

/** Mark and word side by side. `onDark` uses the white word, as the kit's white logo does. */
export function Logo({ height = 28, onDark = false }: { height?: number; onDark?: boolean }) {
  return (
    <View style={styles.row} accessible accessibilityRole="image" accessibilityLabel="eventsli">
      <Mark size={height} />
      <Wordmark height={height} color={onDark ? colors.white : colors.night} />
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'center', gap: 8 },
});
